script:
import json,subprocess,os,sys,hashlib,shutil
from pathlib import Path
repo=Path.cwd();base=repo/'benchmarks/cottage-comparison-20261002';base.mkdir(exist_ok=False)
source=Path('/workspace/scratch/0190a8c72f8a/aperture-cottage-author-a-20261002')
dest=base/'sources/a-v1';dest.mkdir(parents=True)
for p in source.iterdir():
 if not p.is_file() or p.is_symlink():raise RuntimeError('Unexpected author output')
 shutil.copyfile(p,dest/p.name)
(base/'run.mjs').write_text("import {createServer} from "node:http";
import {readFile,mkdir} from "node:fs/promises";
import {resolve,dirname,basename} from "node:path";
import {fileURLToPath} from "node:url";
import {createExamplesRequestHandler} from "../../scripts/serve-examples.mjs";
import {runVerifiedScene} from "../../scripts/verified-webgpu.mjs";
const base=dirname(fileURLToPath(import.meta.url)),repo=resolve(base,"../..");
const [engine,attempt,view="front",edit="base"]=process.argv.slice(2);
if(!["a","b"].includes(engine)||!/^attempt-[0-9]{3}$/.test(attempt))throw Error("Invalid immutable attempt");
const out=resolve(base,"renders",engine,attempt);await mkdir(out,{recursive:true});
const fallback=createExamplesRequestHandler(repo);
const server=createServer(async(req,res)=>{
res.setHeader("Cross-Origin-Opener-Policy","same-origin");res.setHeader("Cross-Origin-Embedder-Policy","require-corp");
const pathname=new URL(req.url,"http://127.0.0.1").pathname;
if(pathname==="/favicon.ico"){res.writeHead(204);res.end();return}
if(pathname.startsWith("/packages/")||pathname.startsWith("/node_modules/")||pathname.startsWith("/worker-modules/"))return fallback(req,res);
let target;
if(["three.webgpu.js","three.core.js"].includes(basename(pathname)))target=resolve(repo,"shadow-lab/src/compare",basename(pathname));
else{
const m=pathname.match(/^\/(a|b)\/([a-zA-Z0-9._-]+)$/);
if(!m||m[2].includes("..")){res.writeHead(404);res.end("Not found");return}
target=resolve(base,"sources",m[1]+"-v1",m[2]);
}
try{const bytes=await readFile(target);res.setHeader("Content-Type",target.endsWith(".html")?"text/html":target.endsWith(".json")?"application/json":"text/javascript");res.end(bytes)}
catch{res.writeHead(404);res.end("Missing immutable source")}
});
await new Promise((ok,fail)=>{server.once("error",fail);server.listen(0,"127.0.0.1",ok)});
try{
const report=await runVerifiedScene({runtimeRoot:process.env.APERTURE_WEBGPU_RUNTIME,scratchRoot:process.env.APERTURE_TMP_RUN,url:`http://127.0.0.1:${server.address().port}/${engine}/index.html?view=${view}&edit=${edit}`,outputPath:resolve(out,"result.json"),screenshotPath:resolve(out,"render.png"),readyGlobal:"__COTTAGE_READY__",viewport:{width:800,height:800},timeout:240000});
console.log(JSON.stringify({status:report.status,proof:report.proof,scene:report.sceneStatus}));
}finally{server.closeAllConnections();await new Promise(ok=>server.close(ok))}
")
pins={'schema':1,'classification':'exploratory independent-author comparison; not formally scored','source':'2c89bd7b1ea6583b990a9745ba9fa4cbf7f28c33','files':{str(p.relative_to(repo)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(dest.iterdir())},'reference':'benchmarks/native-preflight-20261002/preserved-cottage-reference.png','native_three_revision':'185dev, vendored exact bytes pinned in native preflight','settings':{'viewport':[800,800],'pixelRatio':1,'view':'front','edit':'base'},'gaps':['Exact inherited model ID not exposed','Complete authentic visible author transcript export unavailable; retain available messages and tool receipts','Independent blind judgment pending','Prior lost advanced run is not reconstructed']}
(base/'a-v1-pins.json').write_text(json.dumps(pins,indent=2)+'
')
subprocess.run(['node','--check',str(base/'run.mjs')],check=True)
print(json.dumps({'free_bytes_before':shutil.disk_usage('/workspace/scratch/0190a8c72f8a/aperture-tmp').free}),flush=True)
env=os.environ.copy();env['APERTURE_WEBGPU_RUNTIME']=str(repo/'.aperture-env/render-runtime')
cmd=['python3','-B','tools/recovery/runtime_pressure.py','--root','/workspace/scratch/0190a8c72f8a/aperture-tmp','--audit-dir',str(base/'lifecycle-audits'),'run','--job','cottage-a-initial-front','--recreation','Render pinned author a-v1 sources through runVerifiedScene','--','node',str(base/'run.mjs'),'a','attempt-001','front','base']
with (base/'a-attempt-001.log').open('xb') as log:
 proc=subprocess.Popen(cmd,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 for line in proc.stdout:
  log.write(line);log.flush();sys.stdout.buffer.write(line);sys.stdout.buffer.flush()
 raise SystemExit(proc.wait())
